const fs = require('fs');
const path = require('path');

// Read existing English MCQs (first 500)
const engPath = path.join(__dirname, 'public/data/mcqs/english.json');
const existing = JSON.parse(fs.readFileSync(engPath, 'utf8'));

// Take the first 500 if there are already 500
const first500 = existing.slice(0, 500);

const newMCQs = [];

function addEng(id, topic, testTag, difficulty, question, options, answerIndex, explanation) {
    newMCQs.push({
        id: `eng_${id.toString().padStart(4, '0')}`,
        subjectId: "english",
        topic: topic,
        testTag: testTag,
        difficulty: difficulty,
        isPastPaper: true,
        question: question,
        options: options.map(String),
        answer: answerIndex,
        explanation: explanation || `Standard past paper English question for ${topic} (${testTag}).`
    });
}

